function tokenize(s){ return String(s).toLowerCase().match(/[a-z0-9]+/g)||[]; }
function build(text, n){ n=n||2; var toks=tokenize(text); var counts={};
  if(toks.length<n) return {n:n,counts:counts,order:[]};
  for(var i=0;i+n<=toks.length;i++){ var pre=toks.slice(i,i+n-1).join(' '); var nx=toks[i+n-1];
    if(!counts[pre]) counts[pre]={total:0,next:{}}; counts[pre].total++; counts[pre].next[nx]=(counts[pre].next[nx]||0)+1; }
  return {n:n,counts:counts};
}
function predict(model, prefix){ var e=model.counts[prefix]; if(!e) return []; var out=[];
  for(var k in e.next){ out.push({word:k, p:e.next[k]/e.total}); } out.sort(function(a,b){return b.p-a.p;}); return out; }
var EXPORTS={tokenize:tokenize,build:build,predict:predict};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NgramForgePure = EXPORTS; }
